const Fees = () => {
  return (
    <div>
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Fees Management</h1>
      <div className="bg-white rounded-lg shadow p-6">
        <p className="text-gray-500">Fee management coming soon...</p>
      </div>
    </div>
  );
};

export default Fees;
